def _load_csvs():
    with open(f'{REPO}/data/structured_fields.csv', newline='') as f:
        feat = {r['nct_id']: r for r in csv.DictReader(f)}
    reg_path = os.environ.get('TRIALDESIGNBENCH_REGISTRY_CSV', f'{REPO}/data/registry_context.csv')
    try:
        with open(reg_path, newline='') as f:
            reg = {r['nct_id']: r for r in csv.DictReader(f)}
    except FileNotFoundError:
        reg = {}
    with open(f'{REPO}/data/reference_standard.csv', newline='') as f:
        gold = {r['nct_id']: r for r in csv.DictReader(f)}
    return (feat, reg, gold)
_FEAT, _REG, _GOLD = _load_csvs()
# Anonymized case IDs are derived deterministically from the trial list, so no
# external identity map is needed: every model-visible prompt identifies a
# trial by an opaque CASE id only (see the paper's Redaction appendix).
_PMAP = {nct: f'CASE_{i:04d}' for i, nct in enumerate(sorted(_GOLD), start=1)}
try:
    with open(os.environ.get('TRIALDESIGNBENCH_DOSE_EVIDENCE_JSON', f'{REPO}/data/dose_level_evidence.json')) as f:
        _DOSE_LEVEL_EVIDENCE = json.load(f)
except FileNotFoundError:
    _DOSE_LEVEL_EVIDENCE = {}

def _dose_level_evidence_block(nct_id):
    ev = _DOSE_LEVEL_EVIDENCE.get(nct_id, {})
    text = ev.get('dose_level_evidence', 'no explicit dose-level table found in protocol.txt')
    return f'Dose-level escalation schedule (extracted from the full trial protocol):\n{text}'

def load_trial(nct_id):
    f = _FEAT[nct_id]
    r = _REG.get(nct_id, {})
    g = _GOLD[nct_id]
    a3_dir = os.environ.get('TRIALDESIGNBENCH_A3_DIR', f'{REPO}/data/protocol_excerpts')
    a3_path = f'{a3_dir}/{nct_id}.txt'
    a3_text = open(a3_path).read() if os.path.exists(a3_path) else None
    return {'feat': f, 'reg': r, 'gold': g, 'a3_text': a3_text, 'pseudo_id': _PMAP[nct_id]}
B_FIELD_KEYS = ['brief_title', 'phase', 'conditions', 'interventions', 'enrollment', 'start_date', 'B1.phase_i_goal', 'B1.endpoint_nature', 'B3.dlt_definition_text', 'B3.ctcae_version', 'B3.dlt_assessment_window_days', 'B3.interpatient_interval_days', 'B3.interpatient_interval_basis', 'B3.interpatient_safety_floor_days']
C_LATENT_KEYS = ['B1.primary_endpoint_type', 'B1.multiple_or_continuous_toxicity', 'B1.prior_information_available', 'B1.regimen_modality', 'B1.comb_target', 'B1.obd_basis', 'B1.mtd_as_secondary']
E_LATENT_KEYS = ['B1.primary_endpoint_type', 'B1.multiple_or_continuous_toxicity', 'B1.prior_information_available', 'B1.regimen_modality', 'B1.comb_target', 'B1.obd_basis', 'B1.mtd_as_secondary']

def _fmt_fields(feat, keys):
    lines = []
    for k in keys:
        v = feat.get(k, '')
        lines.append(f"- {k}: {(v if v else '(not populated)')}")
    return '\n'.join(lines)

def build_prompt(nct_id, condition):
    t = load_trial(nct_id)
    f, g, pid = (t['feat'], t['gold'], t['pseudo_id'])
    if condition in ('A.1', 'A.2', 'A.3', 'B', 'C'):
        system = ROLE_BLOCK + '\n\n' + FLAT_VOCAB_BLOCK + '\n\n' + SCHEMA_AC
    else:
        system = ROLE_BLOCK + '\n\n' + CLASS_TAXONOMY_BLOCK + '\n\n' + D_TREE_INSTRUCTION_old.format(tree=DECISION_TREE_BLOCK) + '\n\n' + SCHEMA_DE_old
    if condition == 'A.1':
        user = f"Case ID: {pid}\n\nTrial characteristics:\n- Intervention: {f['interventions']}\n- Condition: {f['conditions']}\n- Phase: {f['phase']}\n- Primary objective: {f['B1.phase_i_goal']}"
    elif condition == 'A.2':
        user = f"Case ID: {pid}\n\nRegistry brief summary:\n{t['reg']['brief_summary']}"
    elif condition == 'A.3':
        user = f"Case ID: {pid}\n\nProtocol excerpt (background, rationale, objectives):\n{t['a3_text']}"
    elif condition == 'B':
        user = f"Case ID: {pid}\n\nTrial characteristics:\n{_fmt_fields(f, B_FIELD_KEYS)}\n\nProtocol excerpt (background, rationale, objectives):\n{t['a3_text']}"
    elif condition == 'C':
        c_note = 'In addition to the trial characteristics above, the following latent trial characteristics have been established through prior clinical and statistical analysis and are provided as resolved inputs for your recommendation. These represent judgments that would ordinarily require interpretation of the full protocol; they are supplied here directly.'
        latents = _fmt_fields(f, C_LATENT_KEYS)
        latents += f"\n- final_ai_ratio: {g.get('ai_ratio', '(not populated)')}"
        latents += f"\n- m2_gate: {g.get('m2_gate', '(not populated)')}"
        latents += f"\n- interval_basis: {g.get('interval_basis', '(not populated)')}"
        user = f"Case ID: {pid}\n\nTrial characteristics:\n{_fmt_fields(f, B_FIELD_KEYS)}\n\nProtocol excerpt (background, rationale, objectives):\n{t['a3_text']}\n\n{c_note}\n{latents}"
    elif condition == 'D':
        user = f"Case ID: {pid}\n\nTrial characteristics:\n{_fmt_fields(f, B_FIELD_KEYS)}\n\nProtocol excerpt (background, rationale, objectives):\n{t['a3_text']}"
    elif condition == 'E':
        latents = _fmt_fields(f, E_LATENT_KEYS)
        latents += f"\n- final_ai_ratio: {g.get('ai_ratio', '(not populated)')}"
        latents += f"\n- m2_gate: {g.get('m2_gate', '(not populated)')}"
        latents += f"\n- interval_basis: {g.get('interval_basis', '(not populated)')}"
        user = f"Case ID: {pid}\n\nTrial characteristics:\n{_fmt_fields(f, B_FIELD_KEYS)}\n\nProtocol excerpt (background, rationale, objectives):\n{t['a3_text']}\n\nLatent trial characteristics (resolved for you):\n{latents}"
    else:
        raise ValueError(condition)
    return (system, user)

def build_prompt_v2(nct_id, condition):
    system, user = build_prompt(nct_id, condition)
    if condition in ('D', 'E'):
        system = ROLE_BLOCK + '\n\n' + CLASS_TAXONOMY_BLOCK + '\n\n' + D_TREE_INSTRUCTION_v2.format(tree=DECISION_TREE_BLOCK) + '\n\n' + SCHEMA_DE_v2
    return (system, user)

